UPDATE LIVROS_NOMES N JOIN VW_LOTE_NOMES J ON J.NOME = N.NOME COLLATE utf8mb4_0900_ai_ci SET N.SUGESTAO_TITULO = NULLIF(LEFT(J.TITULO, 300), ''), N.SUGESTAO_AUTOR = NULLIF(LEFT(J.AUTOR, 200), ''), N.MOTIVO = LEFT(J.MOTIVO, 300) WHERE J.CHAVE = '{{chave}}' AND J.CONF <> 'alta' AND N.ESTADO = 'PENDENTE'